import{_ as a,o as t,c as s,a2 as d}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"المساهمة","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/contributing.md","filePath":"ar/guide/contributing.md"}'),o={name:"ar/guide/contributing.md"};function c(i,e,n,l,p,r){return t(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="المساهمة" tabindex="-1">المساهمة <a class="header-anchor" href="#المساهمة" aria-label="Permalink to &quot;المساهمة&quot;">​</a></h1><p>نرحب بالمساهمات بموجب ترخيص Apache License 2.0 (وبموجب CC BY 4.0 للتوثيق والأمثلة). يشرح الملف <a href="https://github.com/TerminalDZ/vidcreat/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a> في المستودع إعداد بيئة التطوير على Windows وmacOS وLinux، وقواعد رسائل الـ commits، وبوابة الجودة التي يجب أن يجتازها كل pull request:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:unit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:browser</span></span></code></pre></div><p>تصف هذه الصفحة أكثر أربعة أنواع من المساهمات شيوعاً.</p><h2 id="add-a-component" tabindex="-1">إضافة مكوّن <a class="header-anchor" href="#add-a-component" aria-label="Permalink to &quot;إضافة مكوّن {#add-a-component}&quot;">​</a></h2><ol><li>أضف schema خصائصه وقيمها الافتراضية في <code>packages/core/src/components/</code>. الخصائص كائنات Zod صارمة؛ أعطِ كل خاصية قيمة افتراضية مناسبة حتى يستطيع المحرر إدراج المكوّن دون أي مدخلات.</li><li>أضف تنفيذه في الـ runtime ضمن <code>packages/runtime/src/components/</code>. يرسم المكوّن عناصر DOM وSVG لأي زمن <code>t</code>، ويجب أن يبقى نقياً: لا <code>Date.now()</code>، ولا عشوائية دون بذرة، ولا مؤقتات. وادعم التخطيط من اليمين إلى اليسار.</li><li>أضف مشهداً يعرضه إلى المعرض في <code>fixtures/golden/components/episode.yaml</code>.</li><li>حدّث الإطارات المرجعية (golden frames) وراجع كل صورة تغيّرت: <code>UPDATE_GOLDEN=1 pnpm test:browser</code> (وفي PowerShell: <code>$env:UPDATE_GOLDEN=1; pnpm test:browser; Remove-Item Env:UPDATE_GOLDEN</code>).</li><li>أعد توليد التوثيق بالأمر <code>pnpm docs:gen</code>، فيلتقط <a href="./../reference/components.html">مرجع المكوّنات</a> الـ schema وصورة المعرض الجديدة.</li></ol><p>ويضم الـ skill المسمى <code>reelforge-contribute-component</code> قائمة تحقق مفصلة.</p><h2 id="add-a-theme" tabindex="-1">إضافة ثيم <a class="header-anchor" href="#add-a-theme" aria-label="Permalink to &quot;إضافة ثيم {#add-a-theme}&quot;">​</a></h2><p>انسخ <code>themes/default.theme.yaml</code> إلى <code>themes/&lt;name&gt;.theme.yaml</code> وغيّر القيم، أو ولّد ثيماً بالأمر <code>pnpm reelforge theme new &lt;name&gt; --accent &quot;#hex&quot;</code>. استخدم الخطوط المضمّنة فقط والتزم بقواعد التباين في <a href="./themes.html">الثيمات والهوية</a>، فاختبار الثيمات يفحص معيار WCAG AA لكل ثيم مضمّن. جرّبه على حلقة من الأمثلة (<code>meta.theme: &lt;name&gt;</code>) باستخدام الأمر <code>reelforge snap</code>. ولا تحتوي الثيمات على أي كود.</p><h2 id="add-an-industry-pack" tabindex="-1">إضافة حزمة قطاعية <a class="header-anchor" href="#add-an-industry-pack" aria-label="Permalink to &quot;إضافة حزمة قطاعية {#add-an-industry-pack}&quot;">​</a></h2><p>توجد الحزمة في <code>packs/&lt;id&gt;/</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packs/&lt;id&gt;/</span></span>
<span class="line"><span>  pack.yaml                     manifest: names, description, theme, blueprints, templates and slots</span></span>
<span class="line"><span>  templates/&lt;template&gt;.en.yaml  an episode with {{slot}} placeholders (one file per language)</span></span>
<span class="line"><span>  templates/&lt;template&gt;.ar.yaml</span></span>
<span class="line"><span>  examples/&lt;name&gt;-en/           a complete example episode (generated)</span></span>
<span class="line"><span>  examples/&lt;name&gt;-ar/</span></span></code></pre></div><ol><li>افتح أولاً <a href="https://github.com/TerminalDZ/vidcreat/issues/new?template=industry_pack_request.yml" target="_blank" rel="noreferrer">طلب حزمة قطاعية</a> للاتفاق على النطاق.</li><li>اكتب <code>pack.yaml</code>؛ يتحقق منه schema الحزم في <code>packages/core/src/packs.ts</code> عند تحميله. استخدم أسماء جهات خيالية فقط، واجعل حدود الحقول ضيقة بما يكفي ليتسع النص في صندوقه.</li><li>اكتب كل قالب بالإنجليزية والعربية، بحيث يدخل كل عنصر عند كلمة من النص.</li><li>أضف المثال إلى <code>scripts/gen-pack-examples.mjs</code> وشغّله، ثم تحقق من الأمثلة وصدّرها مع الخيار <code>--silent</code>.</li><li>أضف دليل القطاع في <code>skills/reelforge-industry-playbooks/references/&lt;id&gt;.md</code> (الجمهور، والنبرة، والحلقات المعتادة، وضوابط الامتثال)، ثم شغّل <code>pnpm docs:gen</code> لتحديث <a href="./../reference/packs.html">فهرس الحزم</a>.</li></ol><h2 id="add-a-skill" tabindex="-1">إضافة skill <a class="header-anchor" href="#add-a-skill" aria-label="Permalink to &quot;إضافة skill {#add-a-skill}&quot;">​</a></h2><p>توجد الـ skills في <code>skills/&lt;name&gt;/SKILL.md</code> بصيغة Agent Skills: مقدمة YAML (front matter) فيها <code>name</code> ووصف <code>description</code> من جملة واحدة يحدد متى يُستخدم الـ skill، تليها تعليمات Markdown موجزة، وتوضع المواد الأطول في <code>references/</code>. اجعل كل skill مركّزاً على مهمة واحدة، ولا تُشِر إلا إلى أوامر وملفات موجودة، واختبره باتباع تعليماته بنفسك على حلقة جديدة. يفحص الأمر <code>pnpm check:skills</code> (ضمن <code>pnpm lint</code>) الصيغة، وتقدّم الأداة <code>get_guide</code> الـ skill الجديد تلقائياً.</p><h2 id="documentation" tabindex="-1">التوثيق <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;التوثيق {#documentation}&quot;">​</a></h2><p>يُبنى الموقع والتوثيق الذي يعمل دون اتصال من ملفات Markdown نفسها في <code>docs/</code>:</p><table tabindex="0"><thead><tr><th>الأمر</th><th>وظيفته</th></tr></thead><tbody><tr><td><code>pnpm docs:gen</code></td><td>يعيد توليد الصفحات المرجعية وصور المكوّنات و<code>docs/components.md</code> و<code>llms-full.txt</code></td></tr><tr><td><code>pnpm docs:dev</code></td><td>يشغّل الموقع محلياً مع إعادة التحميل التلقائي</td></tr><tr><td><code>pnpm docs:site</code></td><td>يبني الموقع العام (بالمسار الأساسي <code>/vidcreat/</code>) في <code>docs/.site</code> (ويفشل عند وجود روابط معطلة)</td></tr><tr><td><code>pnpm docs:local</code></td><td>يبني الموقع نفسه بالمسار الأساسي <code>/docs/</code> في <code>documentation/site</code>، وتقدّمه لوحة التحكم على <code>/docs/</code></td></tr><tr><td><code>pnpm docs</code></td><td>يشغّل <code>docs:gen</code> ثم يبني الملف الواحد <code>documentation/index.html</code> (بالإنجليزية والعربية) ثم <code>docs:local</code></td></tr></tbody></table><p>توجد الصفحات الإنجليزية في <code>docs/guide/</code> و<code>docs/reference/</code>، وتقابلها نسخها العربية في <code>docs/ar/</code>. لا تعدّل الصفحات المولّدة يدوياً أبداً: يشغّل CI الأمر <code>node scripts/check-docs-fresh.mjs</code> ويفشل إذا لم تكن محدّثة. وفي الصفحات العربية أبقِ المصطلحات التقنية والأوامر ومفاتيح YAML بالإنجليزية بين علامتي backtick، وتجنب بدء الفقرة بكلمة لاتينية.</p><h2 id="decision-records" tabindex="-1">سجلات القرارات <a class="header-anchor" href="#decision-records" aria-label="Permalink to &quot;سجلات القرارات {#decision-records}&quot;">​</a></h2><p>لأي تغيير تصميمي كبير، أضف سجل قرار (ADR) في <code>docs/adr/</code> (بالرقم التالي، مع السياق والقرار والعواقب).</p>`,21)])])}const k=a(o,[["render",c]]);export{m as __pageData,k as default};
